import {
  Children,
  cloneElement,
  type CSSProperties,
  type HTMLAttributes,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
} from "react";
import { cx } from "./cx";

type AnyProps = Record<string, unknown>;

function mergeRefs<T>(...refs: Array<Ref<T> | undefined>) {
  return (node: T | null) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const c = ref(node);
        if (typeof c === "function") cleanups.push(c);
      } else if (ref) (ref as { current: T | null }).current = node;
    }
    return cleanups.length ? () => cleanups.forEach((c) => c()) : undefined;
  };
}

/**
 * Renders its only child with the slot's props merged in (class names joined, styles merged, handlers chained, refs
 * composed). This is what `asChild` uses, so a component can style a framework link (`next/link`, a router link)
 * without the library depending on any router.
 */
export function Slot({
  children,
  ref,
  ...props
}: HTMLAttributes<HTMLElement> & { children?: ReactNode; ref?: Ref<HTMLElement> }) {
  const child = Children.only(children);
  if (!isValidElement(child)) return null;
  const childProps = child.props as AnyProps;
  const merged: AnyProps = { ...props, ...childProps };
  for (const key of Object.keys(props)) {
    const a = (props as AnyProps)[key];
    const b = childProps[key];
    if (key === "className") merged.className = cx(a as string, b as string);
    else if (key === "style") merged.style = { ...(a as CSSProperties), ...(b as CSSProperties) };
    else if (/^on[A-Z]/.test(key) && typeof a === "function" && typeof b === "function") {
      merged[key] = (...args: unknown[]) => {
        (b as (...x: unknown[]) => void)(...args);
        (a as (...x: unknown[]) => void)(...args);
      };
    }
  }
  const childRef = childProps.ref as Ref<HTMLElement> | undefined;
  if (ref || childRef) merged.ref = mergeRefs(ref, childRef);
  return cloneElement(child as ReactElement<AnyProps>, merged);
}
